@startuml

class User {
  + UserID : int
  + Name : string
  + Address : string
  + BirthDate : date
}

class BusinessOwner {}
class HungryCustomer {}
class Entertainer {}

class PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : double
}

class Order {
  + OrderID : int
  + OrderDate : datetime
  + LatestDeliveryTime : datetime
  + NumberOfPeople : int
}

class EntertainmentOrder extends Order {
  + EntertainmentType : string
  + Duration : time
}

class DeliveryAddress {}

User "1" -- "*" BusinessOwner
User "1" -- "*" HungryCustomer
User "1" -- "*" Entertainer

BusinessOwner "0..*" -- "0..*" PizzaRestaurant
PizzaRestaurant "0..*" -- "0..*" Pizza

HungryCustomer "0..*" -- "0..*" Order
Order "1" -- "1" DeliveryAddress
Order "0..1" -- "0..1" EntertainmentOrder

Entertainer "0..*" -- "0..*" PizzaRestaurant
PizzaRestaurant "0..*" -- "0..*" Entertainer

@enduml

